import { test } from '@playwright/test';
import { readFile, stat } from 'node:fs/promises';
import path from 'node:path';
await import('../tests/e2e/website-content-projection.spec');
// Keep the production CSP unchanged. Intercept all canonical-origin requests locally;
// no DNS/host modification and no request to the live site.
test.beforeEach(async ({page})=>{
  const goto=page.goto.bind(page);
  page.goto=((url,options)=>goto(new URL(url,'https://solinaridao.com').href,options)) as typeof page.goto;
  const root=path.resolve('work/website-projection-release/hosting');
  await page.route('https://solinaridao.com/**',async route=>{
    const pathname=new URL(route.request().url()).pathname;
    // Match the original negative test: the directory pointer is unavailable.
    // A test-specific newer-pointer mock takes precedence when required.
    if(pathname==='/wrn-content-directory/current.json'){await route.fulfill({status:404,body:'Not found'});return;}
    const relative=pathname==='/'?'index.html':pathname.slice(1);
    const file=path.resolve(root,relative);
    if(!file.startsWith(root+path.sep))throw Error('outside-package');
    try {
      if(!(await stat(file)).isFile())throw Error('missing');
      const type=file.endsWith('.html')?'text/html; charset=utf-8':file.endsWith('.js')?'text/javascript; charset=utf-8':file.endsWith('.css')?'text/css; charset=utf-8':file.endsWith('.json')?'application/json; charset=utf-8':file.endsWith('.webp')?'image/webp':file.endsWith('.png')?'image/png':'text/plain; charset=utf-8';
      await route.fulfill({body:await readFile(file),contentType:type});
    } catch {await route.fulfill({status:404,body:'Not found'});}
  });
});
